package io.github.diodeme.ji.extension;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;

/** Orders, budgets, and attributes prompt fragments without creating another resource registry. */
public final class PromptAssembler {
    private static final Comparator<PromptContributor> ORDER = Comparator
            .comparingInt(PromptContributor::priority)
            .thenComparing(value -> value.source().value())
            .thenComparing(value -> value.id().value());

    private final TokenCounter tokenCounter;

    public PromptAssembler(TokenCounter tokenCounter) {
        this.tokenCounter = Objects.requireNonNull(tokenCounter, "tokenCounter");
    }

    public Assembly assemble(List<? extends PromptContributor> contributors,
                             PromptContributor.PromptContext context, int totalTokenBudget) {
        if (totalTokenBudget < 0) throw new IllegalArgumentException("totalTokenBudget must not be negative");
        Objects.requireNonNull(context, "context");
        var ordered = new ArrayList<>(contributors);
        ordered.sort(ORDER);
        var identities = new HashSet<PromptContributor.ContributorId>();
        var accepted = new ArrayList<Fragment>();
        var rejected = new ArrayList<RejectedContribution>();
        int used = 0;
        for (PromptContributor contributor : ordered) {
            context.cancellation().throwIfCancellationRequested();
            if (!identities.add(contributor.id())) {
                rejected.add(new RejectedContribution(contributor.id(), contributor.source(), "prompt.duplicate_contributor"));
                continue;
            }
            PromptContributor.Contribution contribution;
            try {
                contribution = contributor.contribute(context);
            } catch (RuntimeException failure) {
                rejected.add(new RejectedContribution(contributor.id(), contributor.source(), "prompt.contribution_failed"));
                continue;
            }
            if (contribution.text().isEmpty()) continue;
            int tokens = tokenCounter.count(contribution.text());
            if (tokens < 0) throw new IllegalStateException("token counter returned a negative value");
            if (tokens > contributor.tokenBudget() || tokens > totalTokenBudget - used) {
                rejected.add(new RejectedContribution(contributor.id(), contributor.source(), "prompt.token_budget_exceeded"));
                continue;
            }
            accepted.add(new Fragment(contributor.id(), contributor.source(), contributor.priority(), tokens,
                    contribution.text()));
            used += tokens;
        }
        String text = accepted.stream().map(Fragment::text).reduce("", (left, right) ->
                left.isEmpty() ? right : left + "\n\n" + right);
        return new Assembly(text, accepted, rejected, used, totalTokenBudget);
    }

    @FunctionalInterface
    public interface TokenCounter {
        int count(String text);
    }

    public record Assembly(String text, List<Fragment> fragments, List<RejectedContribution> rejected,
                           int usedTokens, int tokenBudget) {
        public Assembly {
            Objects.requireNonNull(text, "text");
            fragments = List.copyOf(fragments);
            rejected = List.copyOf(rejected);
        }
    }

    public record Fragment(PromptContributor.ContributorId contributorId, ResourceDescriptor.SourceId source,
                           int priority, int tokens, String text) {}

    public record RejectedContribution(PromptContributor.ContributorId contributorId,
                                       ResourceDescriptor.SourceId source, String errorCode) {}
}
